    /// <summary>
    /// Displays the Dear ImGui interactive style editor with metric sliders, palettes, font details, and rendering toggles.
    /// </summary>
    /// <param name="refStyle">Optional reference style to compare against, revert to, and save to.</param>
    /// <remarks>
    /// Ports canonical <c>ImGui::ShowStyleEditor(ImGuiStyle* ref)</c>
    /// (<c>ThirdParty/imgui/imgui_demo.cpp:8656-9004</c>).
    /// </remarks>
    public static void ShowStyleEditor(ImGuiStyle? refStyle = null)
    {
        ImGuiStyle style = ImGui.GetStyle();

        // Default to using internal storage as reference
        if (s_refStyleInit && refStyle == null)
        {
            CopyStyle(s_refSavedStyle, style);
        }
        s_refStyleInit = false;
        refStyle ??= s_refSavedStyle;

        float defaultBorderSize = 1.0f;
        float maxBorderSize = MathF.Max(defaultBorderSize, 2.0f);

        ImGui.PushItemWidth(ImGui.GetWindowWidth() * 0.50f);

        // General section
        ImGui.SeparatorText("General");
        if ((ImGui.GetIO().BackendFlags & ImGuiBackendFlags.RendererHasTextures) == 0)
        {
            ImGui.BulletText("Warning: Font scaling will NOT be smooth, because\nImGuiBackendFlags_RendererHasTextures is not set!");
            ImGui.BulletText("For instructions, see:");
            ImGui.SameLine();
            ImGui.TextLinkOpenURL("docs/BACKENDS.md", "https://github.com/ocornut/imgui/blob/master/docs/BACKENDS.md");
        }

        if (ImGui.ShowStyleSelector("Colors##Selector"))
        {
            CopyStyle(s_refSavedStyle, style);
        }
        ImGui.ShowFontSelector("Fonts##Selector");

        float fontSizeBase = style.FontSizeBase;
        if (ImGui.DragFloat("FontSizeBase", ref fontSizeBase, 0.20f, 5.0f, 100.0f, "%.0f"))
        {
            style.FontSizeBase = fontSizeBase;
        }
        ImGui.SameLine(0.0f, 0.0f);
        ImGui.Text($" (out {ImGui.GetFontSize():F2})");

        float fontScaleMain = style.FontScaleMain;
        if (ImGui.DragFloat("FontScaleMain", ref fontScaleMain, 0.02f, 0.5f, 4.0f))
            style.FontScaleMain = fontScaleMain;

        ImGui.BeginDisabled(ImGui.GetIO().ConfigDpiScaleFonts);
        float fontScaleDpi = style.FontScaleDpi;
        if (ImGui.DragFloat("FontScaleDpi", ref fontScaleDpi, 0.02f, 0.5f, 4.0f))
            style.FontScaleDpi = fontScaleDpi;
        ImGui.SetItemTooltip("When io.ConfigDpiScaleFonts is set, this value is automatically overwritten.");
        ImGui.EndDisabled();

        // Simplified Settings
        float frameRounding = style.FrameRounding;
        if (ImGui.SliderFloat("FrameRounding", ref frameRounding, 0.0f, 12.0f, "%.0f"))
        {
            style.FrameRounding = frameRounding;
            style.GrabRounding = frameRounding;
        }

        bool windowBorder = style.WindowBorderSize > 0.0f;
        if (ImGui.Checkbox("WindowBorder", ref windowBorder))
            style.WindowBorderSize = windowBorder ? defaultBorderSize : 0.0f;

        ImGui.SameLine();
        bool frameBorder = style.FrameBorderSize > 0.0f;
        if (ImGui.Checkbox("FrameBorder", ref frameBorder))
            style.FrameBorderSize = frameBorder ? defaultBorderSize : 0.0f;

        ImGui.SameLine();
        bool popupBorder = style.PopupBorderSize > 0.0f;
        if (ImGui.Checkbox("PopupBorder", ref popupBorder))
            style.PopupBorderSize = popupBorder ? defaultBorderSize : 0.0f;

        // Save/Revert button
        if (ImGui.Button("Save Ref"))
        {
            CopyStyle(refStyle, style);
            CopyStyle(s_refSavedStyle, style);
        }
        ImGui.SameLine();
        if (ImGui.Button("Revert Ref"))
        {
            CopyStyle(style, refStyle);
        }
        ImGui.SameLine();
        HelpMarker(
            "Save/Revert in local non-persistent storage. Default Colors definition are not affected. " +
            "Use \"Export\" below to save them somewhere.");

        ImGui.SeparatorText("Details");

        // Each tab body only submits widgets while its tab item is the selected one, which mirrors the
        // canonical nested BeginTabItem()/EndTabItem() blocks.
        if (ImGui.BeginTabBar("##tabs", ImGuiTabBarFlags.None))
        {
            if (ImGui.BeginTabItem("Sizes"))
            {
                RenderSizesTab(style, maxBorderSize);
                ImGui.EndTabItem();
            }

            if (ImGui.BeginTabItem("Colors"))
            {
                RenderColorsTab(style, refStyle);
                ImGui.EndTabItem();
            }

            if (ImGui.BeginTabItem("Fonts"))
            {
                RenderFontsTab(style);
                ImGui.EndTabItem();
            }

            if (ImGui.BeginTabItem("Rendering"))
            {
                RenderRenderingTab(style);
                ImGui.EndTabItem();
            }

            ImGui.EndTabBar();
        }

        ImGui.PopItemWidth();
    }

