    /// <summary>
    /// Renders the Colors tab body of the style editor: palette export, name filtering, transparency
    /// preview mode, and one editable color row per <see cref="ImGuiCol"/> entry.
    /// </summary>
    /// <param name="style">Style whose palette is edited in place.</param>
    /// <param name="refStyle">Reference palette compared against, and written to by a row's Save button.</param>
    /// <remarks>
    /// Ports the canonical Colors tab body (<c>ThirdParty/imgui/imgui_demo.cpp:8835-8903</c>). Export
    /// writes through the platform clipboard or the console directly rather than through the canonical
    /// logging subsystem.
    /// </remarks>
    private static void RenderColorsTab(ImGuiStyle style, ImGuiStyle refStyle)
    {
        if (ImGui.Button("Export"))
        {
            StringBuilder sb = new();
            sb.AppendLine("// ImVec4[] colors = ImGui.GetStyle().Colors;");
            for (int i = 0; i < (int)ImGuiCol.COUNT; i++)
            {
                ImVec4 col = style.Colors[i];
                string name = ImGui.GetStyleColorName((ImGuiCol)i);
                if (!s_colorsOutputOnlyModified || col != refStyle.Colors[i])
                {
                    int padding = Math.Max(0, 23 - name.Length);
                    sb.AppendLine($"colors[(int)ImGuiCol.{name}]{new string(' ', padding)}= new ImVec4({col.X:F2}f, {col.Y:F2}f, {col.Z:F2}f, {col.W:F2}f);");
                }
            }

            string resultText = sb.ToString();
            if (s_colorsOutputDest == 0)
            {
                ImGui.SetClipboardText(resultText);
            }
            else
            {
                Console.WriteLine(resultText);
            }
        }
        ImGui.SameLine();
        ImGui.SetNextItemWidth(ImGui.GetFontSize() * 10);
        ImGui.Combo("##output_type", ref s_colorsOutputDest, "To Clipboard\0To TTY\0");
        ImGui.SameLine();
        ImGui.Checkbox("Only Modified Colors", ref s_colorsOutputOnlyModified);

        s_colorsFilter.Draw("Filter colors", ImGui.GetFontSize() * 16);

        if (ImGui.RadioButton("Opaque", s_colorsAlphaFlags == ImGuiColorEditFlags.AlphaOpaque)) { s_colorsAlphaFlags = ImGuiColorEditFlags.AlphaOpaque; }
        ImGui.SameLine();
        if (ImGui.RadioButton("Alpha", s_colorsAlphaFlags == ImGuiColorEditFlags.None)) { s_colorsAlphaFlags = ImGuiColorEditFlags.None; }
        ImGui.SameLine();
        if (ImGui.RadioButton("Both", s_colorsAlphaFlags == ImGuiColorEditFlags.AlphaPreviewHalf)) { s_colorsAlphaFlags = ImGuiColorEditFlags.AlphaPreviewHalf; }
        ImGui.SameLine();
        HelpMarker(
            "In the color list:\n" +
            "Left-click on color square to open color picker,\n" +
            "Right-click to open edit options menu.");

        ImGui.SetNextWindowSizeConstraints(new ImVec2(0.0f, ImGui.GetTextLineHeightWithSpacing() * 10), new ImVec2(float.MaxValue, float.MaxValue));
        ImGui.BeginChild("##colors", new ImVec2(0, 0), ImGuiChildFlags.Borders | ImGuiChildFlags.NavFlattened, ImGuiWindowFlags.AlwaysVerticalScrollbar | ImGuiWindowFlags.AlwaysHorizontalScrollbar);
        ImGui.PushItemWidth(ImGui.GetFontSize() * -12);
        for (int i = 0; i < (int)ImGuiCol.COUNT; i++)
        {
            string name = ImGui.GetStyleColorName((ImGuiCol)i);
            if (!s_colorsFilter.PassFilter(name))
                continue;

            ImGui.PushID(i);
            if (ImGui.Button("?"))
                ImGui.DebugFlashStyleColor((ImGuiCol)i);
            ImGui.SetItemTooltip("Flash given color to identify places where it is used.");
            ImGui.SameLine();
            ColorEdit4("##color", ref style.Colors[i], ImGuiColorEditFlags.AlphaBar | s_colorsAlphaFlags);
            if (style.Colors[i] != refStyle.Colors[i])
            {
                ImGui.SameLine(0.0f, style.ItemInnerSpacing.X);
                if (ImGui.Button("Save")) { refStyle.Colors[i] = style.Colors[i]; }
                ImGui.SameLine(0.0f, style.ItemInnerSpacing.X);
                if (ImGui.Button("Revert")) { style.Colors[i] = refStyle.Colors[i]; }
            }
            ImGui.SameLine(0.0f, style.ItemInnerSpacing.X);
            ImGui.TextUnformatted(name);
            ImGui.PopID();
        }
        ImGui.PopItemWidth();
        ImGui.EndChild();
    }

    /// <summary>
    /// Renders the Fonts tab body of the style editor by delegating to the font atlas viewer.
    /// </summary>
    /// <param name="style">The active style. The canonical body does not edit it; the parameter is kept
    /// for symmetry with the other tab helpers.</param>
    /// <remarks>
    /// Ports the canonical Fonts tab body (<c>ThirdParty/imgui/imgui_demo.cpp:8905-8931</c>), whose only
    /// live statement is the <c>ShowFontAtlas(io.Fonts)</c> call.
    /// </remarks>
    private static void RenderFontsTab(ImGuiStyle style)
    {
        ImGuiIO io = ImGui.GetIO();
        ImGui.ShowFontAtlas(io.Fonts);
    }

    /// <summary>
    /// Renders the Rendering tab body of the style editor: anti-aliasing toggles, curve and circle
    /// tessellation tolerances with an interactive circle preview, and global/disabled alpha.
    /// </summary>
    /// <param name="style">Style whose rendering fields are edited in place.</param>
    /// <remarks>
    /// Ports the canonical Rendering tab body (<c>ThirdParty/imgui/imgui_demo.cpp:8933-8997</c>).
    /// </remarks>
    private static void RenderRenderingTab(ImGuiStyle style)
    {
        bool aaLines = style.AntiAliasedLines;
        if (ImGui.Checkbox("Anti-aliased lines", ref aaLines))
            style.AntiAliasedLines = aaLines;
        ImGui.SameLine();
        HelpMarker("When disabling anti-aliasing lines, you'll probably want to disable borders in your style as well.");

        bool aaLineEnds = style.AntiAliasedLineEnds;
        if (ImGui.Checkbox("Anti-aliased line ends", ref aaLineEnds))
            style.AntiAliasedLineEnds = aaLineEnds;
        ImGui.SameLine();
        HelpMarker("Smoother ends on polyline terminations.");

        bool aaFill = style.AntiAliasedFill;
        if (ImGui.Checkbox("Anti-aliased fill", ref aaFill))
            style.AntiAliasedFill = aaFill;

        ImGui.PushItemWidth(ImGui.GetFontSize() * 8);
        float curveTol = style.CurveTessellationTol;
        if (ImGui.DragFloat("Curve Tessellation Tolerance", ref curveTol, 0.02f, 0.10f, 10.0f, "%.2f"))
        {
            if (curveTol < 0.10f) curveTol = 0.10f;
            style.CurveTessellationTol = curveTol;
        }

        // Preview of circle tessellation error
        float curveMaxError = style.CurveTessellationMaxError;
        if (ImGui.DragFloat("Curve Tessellation Max Error", ref curveMaxError, 0.005f, 0.10f, 5.0f, "%.2f", ImGuiSliderFlags.AlwaysClamp))
            style.CurveTessellationMaxError = curveMaxError;

        bool showSamples = ImGui.IsItemActive();
        if (showSamples)
            ImGui.SetNextWindowPos(ImGui.GetCursorScreenPos());
        if (showSamples && ImGui.BeginTooltip())
        {
            ImGui.TextUnformatted("(R = radius, N = approx number of segments)");
            ImGui.Spacing();
            ImDrawList drawList = ImGui.GetWindowDrawList();
            float minWidgetWidth = ImGui.CalcTextSize("R: MMM\nN: MMM").X;
            for (int n = 0; n < 8; n++)
            {
                const float radMin = 5.0f;
                const float radMax = 70.0f;
                float rad = radMin + (radMax - radMin) * (float)n / (8.0f - 1.0f);

                ImGui.BeginGroup();
                int segmentCount = CalcCircleAutoSegmentCount(rad, style.CurveTessellationMaxError);
                ImGui.Text($"R: {rad:F0}\nN: {segmentCount}");

                float canvasWidth = MathF.Max(minWidgetWidth, rad * 2.0f);
                float offsetX = MathF.Floor(canvasWidth * 0.5f);
                float offsetY = MathF.Floor(radMax);

                ImVec2 p1 = ImGui.GetCursorScreenPos();
                drawList.AddCircle(new ImVec2(p1.X + offsetX, p1.Y + offsetY), rad, ImGui.GetColorU32(ImGuiCol.Text));
                ImGui.Dummy(new ImVec2(canvasWidth, radMax * 2));

                ImGui.EndGroup();
                ImGui.SameLine();
            }
            ImGui.EndTooltip();
        }
        ImGui.SameLine();
        HelpMarker("When drawing circle primitives with \"num_segments == 0\" tessellation will be calculated automatically.");

        float alpha = style.Alpha;
        if (ImGui.DragFloat("Global Alpha", ref alpha, 0.005f, 0.20f, 1.0f, "%.2f"))
            style.Alpha = alpha;

        float disabledAlpha = style.DisabledAlpha;
        if (ImGui.DragFloat("Disabled Alpha", ref disabledAlpha, 0.005f, 0.0f, 1.0f, "%.2f"))
            style.DisabledAlpha = disabledAlpha;
        ImGui.SameLine();
        HelpMarker("Additional alpha multiplier for disabled items (multiply over current value of Alpha).");
        ImGui.PopItemWidth();
    }

    #endregion

    #region Helper Methods

    private static string GetTreeLinesFlagsName(ImGuiTreeNodeFlags flags)
    {
        if (flags == ImGuiTreeNodeFlags.DrawLinesNone) return "DrawLinesNone";
        if (flags == ImGuiTreeNodeFlags.DrawLinesFull) return "DrawLinesFull";
        if (flags == ImGuiTreeNodeFlags.DrawLinesToNodes) return "DrawLinesToNodes";
        return "";
    }

    private static void SliderVec2(string label, ImVec2 val, Action<ImVec2> setter, float vMin, float vMax, string format)
    {
        float[] arr = [val.X, val.Y];
        if (ImGui.SliderFloat2(label, arr, vMin, vMax, format))
        {
            setter(new ImVec2(arr[0], arr[1]));
        }
    }

    private static void SliderFloatVal(string label, float val, Action<float> setter, float vMin, float vMax, string format)
    {
        if (ImGui.SliderFloat(label, ref val, vMin, vMax, format))
        {
            setter(val);
        }
    }

    private static void DragFloatVal(string label, float val, Action<float> setter, float vSpeed, float vMin, float vMax, string format)
    {
        if (ImGui.DragFloat(label, ref val, vSpeed, vMin, vMax, format))
        {
            setter(val);
        }
    }

    private static int CalcCircleAutoSegmentCount(float radius, float maxError)
    {
        float angle = MathF.Acos(1.0f - MathF.Min(maxError, radius) / radius);
        int segments = (int)MathF.Ceiling(MathF.PI / angle);
        segments = ((segments + 1) / 2) * 2;
        return Math.Clamp(segments, 4, 512);
    }

